package au.aumanet.app;import android.content.Context;import java.util.concurrent.*;final class GroupMessageDeliveryService{static final class Lease{final GroupMessages owner;Lease(GroupMessages owner){this.owner=owner;}}static volatile GroupMessages owner;static volatile Lease current;static volatile CountDownLatch captured,release;static volatile boolean deny;static Lease hold(Context context)throws Exception{if(deny)throw new IllegalStateException("Denied foreground owner");Lease lease=current;if(lease==null||lease.owner!=owner)current=lease=new Lease(owner);CountDownLatch seen=captured,wait=release;if(seen!=null){seen.countDown();if(!wait.await(5,TimeUnit.SECONDS))throw new IllegalStateException("Test hold timeout");}return lease;}static void release(Context context,Lease expected){if(current==expected)current=null;}static void releaseOwner(Context context,GroupMessages expected){Lease lease=current;if(lease!=null&&lease.owner==expected)current=null;}static boolean held(){return current!=null;}}
